package com.nigson.acceptance.carrier;
import java.time.*;
import java.net.*;
import java.net.http.*;
import java.util.*;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.acceptance.files.StorageFixture;
import com.nigson.acceptance.provider.JobHttpAcceptance;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;
/** Real BFF sessions/CSRF and private workload JWT, with actual immutable private label proof. */
public final class CarrierCancellationHttpAcceptance {
 private CarrierCancellationHttpAcceptance(){}
 public static void configure(Map<String,Object> properties){if(System.getenv("NIGSON_TEST_CARRIER")!=null){properties.put("NIGSON_CARRIER_CANCELLATION_ENABLED","true");properties.put("NIGSON_CARRIER_CANCELLATION_DELAY_MS","300000");}}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,JobHttpAcceptance.Fixture upstream)throws Exception{if(System.getenv("NIGSON_TEST_CARRIER")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);String session=null;try(var f=new ShipmentFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class));var storage=new StorageFixture(System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE"))){CarrierContextPersistenceTest.freeze(f);var shipment=f.create("5","FEDEX",null,"cancel-http");CarrierReconciliationPersistenceTest.ngMarket(f);UUID booking=f.inventory.jdbc.queryForObject("SELECT booking_request_id FROM commerce.shipment WHERE id=?",UUID.class,shipment.id());var label=CarrierResultPersistenceTest.putLabel(storage,shipment.id(),UUID.randomUUID(),booking.toString());app.getBean(CarrierResultService.class).accept(CarrierResultPersistenceTest.proof(),shipment.id(),label,UUID.randomUUID());f.inventory.jdbc.update("UPDATE commerce.party SET identity_issuer=? WHERE id=?",upstream.issuer,f.inventory.actor.party());var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,f.inventory.actor.party(),upstream.issuer,f.inventory.actor.party().toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));String uri=base+"/api/v1/staff/shipments/"+shipment.id()+"/carrier-cancellation",cookie="__Host-nigson-session="+session,body="{\"reason\":\"Synthetic carrier cancellation request\"}",key=UUID.randomUUID().toString();
 assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body))).statusCode()).isEqualTo(401);
 assertThat(send(http,command(uri,cookie,"wrong",body,key,1)).statusCode()).isEqualTo(401);
 assertThat(send(http,command(uri,cookie,csrf,body,"version",2)).statusCode()).isEqualTo(412);
 var accepted=send(http,command(uri,cookie,csrf,body,key,1));assertThat(accepted.statusCode()).as("cancellation response: %s",accepted.body()).isEqualTo(202);var dto=EventCodec.JSON.readTree(accepted.body());assertThat(dto.propertyNames()).containsExactlyInAnyOrder("id","shipmentId","state","version","shipmentVersion","errorCode");assertThat(dto.path("state").asString()).isEqualTo("REQUESTED");assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).GET()).statusCode()).isEqualTo(200);
 var receipt=new CarrierCancellationValues.Receipt(UUID.randomUUID(),UUID.fromString(dto.path("id").asString()),shipment.id(),booking,"123456789012","MOCK","CANCELLED",Instant.now(),"NONE");String result=base+"/internal/v1/carrier/cancellation-results",wire=EventCodec.JSON.writeValueAsString(receipt);assertThat(send(http,callback(result,upstream.workload("logistics.read","nigson-integration","nigson-commerce"),receipt.commandId(),wire)).statusCode()).isEqualTo(401);String token=upstream.workload("logistics.write","nigson-integration","nigson-commerce");assertThat(send(http,callback(result,token,receipt.commandId(),wire).header("X-Nigson-Actor","invalid")).statusCode()).isEqualTo(401);var cancelled=send(http,callback(result,token,receipt.commandId(),wire));assertThat(cancelled.statusCode()).as("result: %s",cancelled.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(cancelled.body()).path("state").asString()).isEqualTo("CANCELLED");assertThat(send(http,callback(result,token,receipt.commandId(),wire)).statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(send(http,command(uri,cookie,csrf,body,key,1)).body()).path("state").asString()).isEqualTo("CANCELLED");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");f.inventory.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",f.inventory.actor.party());assertThat(send(http,HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).GET()).statusCode()).isEqualTo(403);
 }finally{if(session!=null)sessions.logout(session);}}
 private static HttpRequest.Builder command(String uri,String cookie,String csrf,String body,String key,long version){return HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key).header("If-Match","\""+version+"\"").header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpRequest.Builder callback(String uri,String token,UUID key,String body){return HttpRequest.newBuilder(URI.create(uri)).header("Authorization","Bearer "+token).header("Idempotency-Key",key.toString()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
